SALAIRE = {"hote":(250,450,800),"serveur":(200,350,600),"barman":(300,550,1000),"portier":(200,400,700)}
TON = {1:"slightly awkward and inexperienced demeanor", 2:"composed professional demeanor", 3:"commanding, charismatic presence"}
def prompt(look, n):
    return (f"Professional portrait photograph, head and shoulders, of {look}, {TON[n]}. "
            "Warm low-key lighting, dark wood-paneled background, shallow depth of field, cinematic, "
            "muted warm colors, realistic, 35mm film look, no text, no watermark.")
def q(s): return "null" if s is None else "'" + s.replace("'", "''") + "'"
assert len(P) == 36
ins1, ins2 = [], []
for i,(poste,n,slug,nom,age,pres,trait,secret,look) in enumerate(P):
    ins1.append(f"({q(slug)},{q(poste)},{n},{q(nom)},{age},{q(pres)},{q(trait)},{SALAIRE[poste][n-1]},{i})")
    ins2.append(f"({q(slug)},{q(secret)},{q(prompt(look,n))})")
print("insert into public.personnel (slug,poste,niveau,nom,age,presentation,trait,salaire_hebdo,ordre) values\n" + ",\n".join(ins1) + ";")
print("insert into public.personnel_mj (slug,secret,prompt) values\n" + ",\n".join(ins2) + ";")
